import codecs
input()
for name in ('ascii', 'latin_1', 'utf_8', 'utf_7', 'charmap', 'unicode_escape', 'raw_unicode_escape'):
    for operation in ('encode', 'decode'):
        fn = getattr(codecs, name + '_' + operation)
        value = '' if operation == 'encode' else b''
        for kind in ('missing', 'extra', 'keywords', 'source', 'errors', 'nul'):
            try:
                if kind == 'missing': result = fn()
                elif kind == 'extra': result = fn(value, None, None, None)
                elif kind == 'keywords': result = fn(value, errors=None)
                elif kind == 'source': result = fn(None)
                elif kind == 'errors': result = fn(value, True)
                else: result = fn(value, '\0')
                print(name, operation, kind, 'ok', result)
            except Exception as error:
                print(name, operation, kind, type(error).__name__, error.args, error.__cause__, error.__context__, error.__traceback__ is not None)
        print(name, operation, 'empty', fn(value))
class Final:
    def __bool__(self):
        input()
        raise RuntimeError('final failed')
for name in ('utf_8', 'utf_7', 'unicode_escape', 'raw_unicode_escape'):
    try:
        getattr(codecs, name + '_decode')(b'', 'strict', Final())
    except Exception as error:
        print(name, 'final', type(error).__name__, error.args, error.__traceback__ is not None)
